// A row that follows its neighbours, and is reordered by a drag or by the keyboard.
<Motion
  as="li"
  name="reflow"
  gesture="reorder-row"
  onMotionReorder={(event) => {
    event.preventDefault();
    move(event.detail.from, event.detail.to);
  }}
>
  {label}
</Motion>

function Sheet({ open }: { open: boolean }) {
  const panel = useMotion('slide', { present: open });
  return panel.mounted && <div ref={panel.ref}>…</div>;
}

// A submenu that stays in the DOM, hidden while closed: its links are in the server HTML.
function Submenu({ open }: { open: boolean }) {
  const menu = useMotion('fade', { present: open });
  return <ul ref={menu.ref} hidden={!open}>…</ul>;
}

// A row that is swiped away removes itself from the list; a reorder step moves the item in the state.
const dismiss = useMotionGesture<HTMLLIElement>('swipe-dismiss', {
  onSwipe: () => setItems(items => items.filter(item => item.id !== id)),
});
return <li ref={dismiss.ref}>{label}</li>;

// A reorder list: preventing the move keeps the DOM as it is, and the state moves the item, so React renders the new order
// and the layout motion animates it.
const row = useMotionGesture<HTMLLIElement>('reorder-row', {
  onReorder: (event) => {
    event.preventDefault();
    setItems(items => moveItem(items, event.detail.from, event.detail.to));
  },
});
return <li ref={row.ref}>{label}</li>;

// A hero whose title, subtitle and actions enter one after the other.
const hero = useMotionSequence<HTMLElement>('hero');
return <section ref={hero.ref}>…</section>;

// The card tilts with the pointer: its class reads `--udx-motion-value-tilt`.
const tilt = useMotionValue<HTMLDivElement>('tilt');
return <div ref={tilt.ref} className="tilt-card">…</div>;

const tilt = useMotionValue<HTMLDivElement>('tilt');
const percent = useMotionValueSnapshot(tilt);
return <div ref={tilt.ref}>{percent === undefined ? '' : Math.round(percent * 100)}</div>;
